/**
 * The contract `badge.tsx` (native) and `badge.web.tsx` (web) both implement.
 * Its own module because Metro resolves `./badge` to `badge.web.tsx` on web.
 *
 * The variant names are shadcn's six — `default`, `secondary`, `destructive`,
 * `outline`, `ghost`, `link` — with their meanings, plus `positive`, `warning` and `info`,
 * which shadcn's token set has no answer for and cubeui's has (see `badge.tsx`'s header). Each
 * coloured meaning also has a `-soft` form — a tint, an edge and a dot in the hue, with the words in
 * the foreground — for a badge that is not the main thing on its row.
 *
 * The web half also takes every `<span>` attribute (`style`, `title`, `onClick`,
 * `data-*`) and shadcn's `asChild`, so a DOM call site ports unchanged. Those
 * extras are web only.
 */
import { cva } from "class-variance-authority";
import { Children, type ReactNode } from "react";

/** The meanings a badge can carry, which pick its colours. */
export type BadgeVariant =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost"
  | "link"
  | "positive"
  | "warning"
  | "info"
  | "destructive-soft"
  | "positive-soft"
  | "warning-soft"
  | "info-soft";

type SoftVariant = "destructive-soft" | "positive-soft" | "warning-soft" | "info-soft";

/**
 * The dot drawn before a soft badge's words, in the hue. The words themselves are the foreground,
 * not the hue: `text-negative` on `bg-negative/10` is 3.99:1 in the default light palette, and
 * positive and warning are under 4.5:1 too — the reason `Alert` keeps its text the foreground. So
 * the hue is in the tint, the edge and this dot. A literal per hue, so Tailwind finds each class.
 */
const SOFT_DOT = {
  "destructive-soft": "bg-negative",
  "positive-soft": "bg-positive",
  "warning-soft": "bg-warning",
  "info-soft": "bg-info",
} satisfies Record<SoftVariant, string>;

function isSoft(variant: BadgeVariant | null | undefined): variant is SoftVariant {
  return variant !== null && variant !== undefined && variant in SOFT_DOT;
}

/** The soft variants' dot class, `null` for every other variant. */
export function badgeSoftDotClass(variant: BadgeVariant | null | undefined): string | null {
  return isSoft(variant) ? `size-1.5 shrink-0 rounded-full ${SOFT_DOT[variant]}` : null;
}

export type BadgeProps = {
  variant?: BadgeVariant | undefined;
  /**
   * Overrides the variant's background with a literal colour — for a badge
   * standing in for a user-chosen tag or category. Passing it also drops the
   * variant's label colour, since the caller's background is unknown and
   * `text-neutral-foreground` would be a guess. Pair it with `readableTextColor`
   * when the label has to stay legible on an arbitrary hue.
   */
  backgroundColor?: string | undefined;
  /**
   * Overrides the label's colour, for the same case as `backgroundColor`: with an
   * arbitrary hue behind it, neither the variant's label colour nor the
   * `text-foreground` fallback is guaranteed to be legible. `readableTextColor`
   * is what computes the value to pass.
   */
  textColor?: string | undefined;
  className?: string | undefined;
  /**
   * What the dot stands for, exposed as its accessible name. In the pill form
   * the text is already the name, so there it only feeds `removeLabel`'s default
   * when the children hold no text of their own.
   */
  label?: string | undefined;
  /**
   * Draws a trailing ✕, a button of its own, that calls this — a tag or a filter
   * chip the user can take off. The ✕ is in the label's colour, and pressing it
   * reaches nothing else on the badge. Ignored by the dot, which has no room for
   * it, and by the web half's `asChild`, whose one child is the whole badge.
   */
  onRemove?: (() => void) | undefined;
  /**
   * Sets the label in monospace at normal weight, for a machine string: an id, a tool name, a cron
   * expression. It is on the label's type, not the container, so it reaches the `Text` on native.
   * `variant` stays free for colour.
   */
  mono?: boolean | undefined;
  /**
   * Pulses the dot, for something live: a run in progress, a connection that is up. The dot only;
   * a badge with children ignores it. It stops for a reader who asked for reduced motion.
   */
  pulse?: boolean | undefined;
  /** The ✕'s accessible name. Defaults to `Remove <text>`, the badge's own text. */
  removeLabel?: string | undefined;
  /**
   * The label: text, a number, or elements such as an icon beside text. Absent —
   * including an empty string — collapses the badge to a dot.
   */
  children?: ReactNode;
};

/** One breath of `pulse`, and how faint the dot gets: Tailwind's `animate-pulse`. */
export const BADGE_PULSE_MS = 2000;
export const BADGE_PULSE_LOW = 0.5;

/** Whether `children` holds anything to show, which is what decides pill or dot. */
export function badgeHasLabel(children: ReactNode): boolean {
  return children !== undefined && children !== null && children !== false && children !== "";
}

/**
 * The ✕'s default name: `Remove` and the badge's text — its string and number
 * children — or `label` when the children are all elements.
 */
export function badgeRemoveLabel(children: ReactNode, label?: string | undefined): string {
  const text = Children.toArray(children)
    .filter((child) => typeof child === "string" || typeof child === "number")
    .join("")
    .trim();
  const name = text || label;
  return name ? `Remove ${name}` : "Remove";
}

/**
 * No `align-self` here: a badge beside a select or a button takes the row's `items-center` like
 * everything else in it. Keeping it from stretching down a column is each half's job — `w-fit`
 * on the web, `self-start` on native, where Yoga has no fit-content.
 *
 * The container: shape and background. `shape` is derived from whether a label
 * was passed, not taken as a prop — a dot is what a badge with nothing to say
 * already is, and making it a second axis would allow the two states that mean
 * nothing: a dot with a label it cannot show, and an empty pill.
 */
export const badgeContainerVariants = cva("shrink-0 rounded-full border border-transparent", {
  variants: {
    variant: {
      default: "bg-neutral",
      secondary: "bg-foreground/10",
      destructive: "bg-negative",
      outline: "border-foreground/10 bg-transparent",
      ghost: "bg-transparent",
      link: "bg-transparent",
      positive: "bg-positive",
      warning: "bg-warning",
      info: "bg-info",
      "destructive-soft": "border-negative/40 bg-negative/10",
      "positive-soft": "border-positive/40 bg-positive/10",
      "warning-soft": "border-warning/40 bg-warning/10",
      "info-soft": "border-info/40 bg-info/10",
    },
    shape: {
      pill: "flex-row items-center justify-center gap-1 px-2 py-0.5",
      dot: "h-2 w-2",
    },
  },
  // A dot has no words to carry the hue, so a soft one is the solid colour: a tint 8px wide is
  // not there.
  compoundVariants: [
    { variant: "destructive-soft", shape: "dot", className: "border-transparent bg-negative" },
    { variant: "positive-soft", shape: "dot", className: "border-transparent bg-positive" },
    { variant: "warning-soft", shape: "dot", className: "border-transparent bg-warning" },
    { variant: "info-soft", shape: "dot", className: "border-transparent bg-info" },
  ],
  defaultVariants: { variant: "default", shape: "pill" },
});

/** The label's colour and nothing else, per variant. */
const BADGE_INK = {
  default: "text-neutral-foreground",
  secondary: "text-foreground",
  destructive: "text-negative-foreground",
  outline: "text-foreground",
  ghost: "text-foreground",
  link: "text-info",
  positive: "text-positive-foreground",
  warning: "text-warning-foreground",
  info: "text-info-foreground",
  "destructive-soft": "text-foreground",
  "positive-soft": "text-foreground",
  "warning-soft": "text-foreground",
  "info-soft": "text-foreground",
} satisfies Record<BadgeVariant, string>;

/** The label's type and colour, per variant, and set in monospace for `mono`. */
export const badgeTextVariants = cva("text-xs", {
  variants: {
    variant: { ...BADGE_INK, link: "text-info underline-offset-4" },
    mono: { false: "font-semibold", true: "font-mono font-normal" },
  },
  defaultVariants: { variant: "default", mono: false },
});

/**
 * The ✕'s colour on native, where nothing inherits: the label's ink without its
 * type, which an `<Svg>` has no use for. The web ✕ takes `currentColor` instead.
 */
export const badgeInkVariants = cva("", {
  variants: { variant: BADGE_INK },
  defaultVariants: { variant: "default" },
});

/** The label's class when `backgroundColor` replaced the variant's own. */
export function badgeTextFallback(mono = false): string {
  return mono
    ? "text-xs font-mono font-normal text-foreground"
    : "text-xs font-semibold text-foreground";
}

/** `badgeInkVariants`' counterpart, for when `backgroundColor` replaced the variant's own. */
export const badgeInkFallback = "text-foreground";

/**
 * The badge's icon size — the one the web half gives an `<svg>` child — and so the ✕'s. It is
 * shorter than the label's line, so the ✕ never makes the pill taller.
 */
export const badgeIconClass = "size-3 shrink-0";

/**
 * shadcn's `badgeVariants`: the whole pill's classes, container and label together, for dressing
 * something else — a link, a button — as a badge. The two class maps never touch the same
 * property, so they join without merging.
 */
export function badgeVariants({
  variant,
  shape,
}: {
  variant?: BadgeVariant | null | undefined;
  shape?: "pill" | "dot" | null | undefined;
} = {}): string {
  return `${badgeContainerVariants({ variant, shape })} ${badgeTextVariants({ variant })}`;
}

/**
 * A small pill stating what something is or what state it is in, and with no children the dot
 * that stands for the same thing in a row too tight for words. `badge.web.tsx` is the web
 * counterpart and `badge-base.ts` holds the contract and the class maps they share.
 *
 * The variants are shadcn's, with shadcn's meanings, plus `positive` and `warning`, which are
 * tokens of cubeui's own. Their fills are Tailwind's 700s because white text on a lighter shade is
 * under 4.5:1. Each string child is wrapped in a `Text` carrying the label colour, since native
 * does not inherit it. `onRemove` adds a trailing ✕ in its own `Pressable`.
 */
import { Children, useEffect, useRef, useState } from "react";
import { AccessibilityInfo, Animated, Easing, Pressable, Text, View } from "react-native";
import {
  BADGE_PULSE_LOW,
  BADGE_PULSE_MS,
  type BadgeProps,
  type BadgeVariant,
  badgeContainerVariants,
  badgeHasLabel,
  badgeIconClass,
  badgeInkFallback,
  badgeInkVariants,
  badgeRemoveLabel,
  badgeSoftDotClass,
  badgeTextFallback,
  badgeTextVariants,
  badgeVariants,
} from "@/components/ui/badge-base";
import { X } from "@/components/ui/icons";
import { IconClassContext } from "@/components/ui/icons-base";
import { cn } from "@/lib/utils";

/** A 12px glyph grown to about 28 by 28 of touch, without growing the pill. */
const REMOVE_HIT_SLOP = { top: 8, bottom: 8, left: 6, right: 8 } as const;

/** Tailwind's `animate-pulse` curve, so the device breathes the way the web does. */
const PULSE_EASE_IN = 0.4;
const PULSE_EASE_OUT = 0.6;
const PULSE_EASING = Easing.bezier(PULSE_EASE_IN, 0, PULSE_EASE_OUT, 1);

/** `View`, which NativeWind hands a `className` to, able to take an animated `opacity`. */
const PulsingView = Animated.createAnimatedComponent(View);

/** Whether the reader asked the system for reduced motion, kept up to date as they change it. */
function useReduceMotion(): boolean {
  const [reduce, setReduce] = useState(false);
  useEffect(() => {
    let live = true;
    AccessibilityInfo.isReduceMotionEnabled().then((value) => {
      if (live) {
        setReduce(value);
      }
    });
    const subscription = AccessibilityInfo.addEventListener("reduceMotionChanged", setReduce);
    return () => {
      live = false;
      subscription.remove();
    };
  }, []);
  return reduce;
}

/**
 * The dot's opacity for `pulse`: a loop on the native driver while it runs, still at 1 otherwise.
 * A CSS keyframe is a class NativeWind resolves to nothing on device, so this is `Animated`, as
 * `Skeleton`'s pulse is.
 */
function usePulse(running: boolean): Animated.Value {
  const opacity = useRef(new Animated.Value(1)).current;
  useEffect(() => {
    if (running === false) {
      opacity.setValue(1);
      return;
    }
    const half = { duration: BADGE_PULSE_MS / 2, easing: PULSE_EASING, useNativeDriver: true };
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, { toValue: BADGE_PULSE_LOW, ...half }),
        Animated.timing(opacity, { toValue: 1, ...half }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [opacity, running]);
  return opacity;
}

export type { BadgeProps, BadgeVariant };

/** A small pill naming a kind or a state, or a dot of the same colour when it has no children. */
export function Badge({
  variant = "default",
  backgroundColor,
  textColor,
  className,
  label,
  onRemove,
  removeLabel,
  mono = false,
  pulse = false,
  children,
}: BadgeProps) {
  const shape = badgeHasLabel(children) ? "pill" : "dot";
  const reduceMotion = useReduceMotion();
  const pulsing = pulse && shape === "dot" && reduceMotion === false;
  const opacity = usePulse(pulsing);
  const textClass = backgroundColor
    ? badgeTextFallback(mono)
    : badgeTextVariants({ variant, mono });
  const inkClass = backgroundColor ? badgeInkFallback : badgeInkVariants({ variant });
  // Not with `backgroundColor`: the caller's colour replaced the tint the dot belongs to.
  const softDot = shape === "pill" && !backgroundColor ? badgeSoftDotClass(variant) : null;
  const dotName = label
    ? ({ role: "img", "aria-label": label } as const)
    : ({ "aria-hidden": true } as const);

  return (
    <PulsingView
      // Yoga stretches a child across a column and has no fit-content to stop it, so on native the
      // badge pins itself to the start. In a centred row, pass `className="self-center"`.
      className={cn("self-start", badgeContainerVariants({ variant, shape }), className)}
      style={[backgroundColor ? { backgroundColor } : null, pulsing ? { opacity } : null]}
      // A dot carries meaning and no text, so it is named or it is decoration;
      // the same split `color-dot` makes, for the same reason.
      {...(shape === "dot" ? dotName : {})}
    >
      {softDot ? <View aria-hidden className={softDot} /> : null}
      {/* An icon passed as a child takes the badge's ink at the web's `[&>svg]:size-3`. */}
      <IconClassContext.Provider value={cn("size-3", textClass)}>
        {shape === "pill"
          ? Children.map(children, (child) =>
              typeof child === "string" || typeof child === "number" ? (
                <Text
                  numberOfLines={1}
                  className={textClass}
                  {...(textColor ? { style: { color: textColor } } : {})}
                >
                  {child}
                </Text>
              ) : (
                child
              ),
            )
          : null}
      </IconClassContext.Provider>
      {shape === "pill" && onRemove ? (
        <Pressable
          onPress={onRemove}
          // The `role` is hand-written because a `<button>` has no native counterpart.
          role="button"
          aria-label={removeLabel ?? badgeRemoveLabel(children, label)}
          hitSlop={REMOVE_HIT_SLOP}
        >
          <X
            className={cn(badgeIconClass, inkClass)}
            // An inline prop wins over the colour the class maps to, as `style` does on the `Text`.
            {...(textColor ? { color: textColor } : {})}
          />
        </Pressable>
      ) : null}
    </PulsingView>
  );
}

export { badgeVariants };

/**
 * The web badge: one `<span>`, as shadcn's is. `badge.tsx` is the native
 * counterpart, and its header has the reasoning behind the variants and the dot;
 * `badge-base.ts` holds the contract and the class maps they share.
 *
 * On the DOM, colour inherits, so the label class sits on the container and the
 * children — text, a number, an icon beside text — render straight inside it.
 * It also takes every `<span>` attribute (`style`, `title`, `onClick`, `data-*`)
 * and shadcn's `asChild`, which hands the classes to the single child — a link
 * dressed as a badge. Those extras are web only.
 *
 * `onRemove` adds a trailing ✕ as a `<button type="button">`, so it never
 * submits a form it sits in, and its click stops at the button so a badge's own
 * `onClick` does not fire under it. The glyph is `currentColor`, so it follows
 * the label through `textColor`, a variant or a hover. Its padding is the hit
 * area and a negative margin of the same size takes it back out of the layout,
 * which keeps the pill the height it was; it stays inside the pill's edge
 * because `overflow-hidden` would clip a target that did not.
 */
import { Slot } from "radix-ui";
import type * as React from "react";
import {
  type BadgeProps,
  type BadgeVariant,
  badgeContainerVariants,
  badgeHasLabel,
  badgeIconClass,
  badgeRemoveLabel,
  badgeSoftDotClass,
  badgeTextFallback,
  badgeTextVariants,
  badgeVariants,
} from "@/components/ui/badge-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

export type { BadgeProps, BadgeVariant };

/** A small pill naming a kind or a state, or a dot of the same colour when it has no children. */
export function Badge({
  variant = "default",
  backgroundColor,
  textColor,
  className,
  label,
  onRemove,
  removeLabel,
  mono = false,
  pulse = false,
  asChild = false,
  style,
  children,
  ...props
}: BadgeProps &
  Omit<React.ComponentProps<"span">, keyof BadgeProps> & {
    /** Render the single child with the badge's classes instead of a `<span>`. */
    asChild?: boolean | undefined;
  }) {
  const shape = asChild || badgeHasLabel(children) ? "pill" : "dot";
  const Comp = asChild ? Slot.Root : "span";
  const dotName = label
    ? ({ role: "img", "aria-label": label } as const)
    : ({ "aria-hidden": true } as const);

  const softDot = shape === "pill" && !backgroundColor ? badgeSoftDotClass(variant) : null;
  const pill =
    shape === "pill" ? (
      <>
        {softDot ? <span aria-hidden className={softDot} /> : null}
        {children}
        {onRemove ? (
          <button
            type="button"
            aria-label={removeLabel ?? badgeRemoveLabel(children, label)}
            className="-my-1 -mr-1.5 -ml-1 inline-flex cursor-pointer items-center justify-center rounded-full p-1 text-inherit outline-none hover:opacity-75 focus-visible:opacity-75"
            onClick={(event) => {
              event.stopPropagation();
              onRemove();
            }}
            // The keys that press it, stopped too, so a badge's own `onKeyDown` does not act on them.
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.stopPropagation();
              }
            }}
          >
            <X className={badgeIconClass} aria-hidden />
          </button>
        ) : null}
      </>
    ) : null;

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      className={cn(
        "inline-flex w-fit overflow-hidden whitespace-nowrap transition-colors focus-visible:outline-none [&>svg]:pointer-events-none [&>svg]:size-3",
        badgeContainerVariants({ variant, shape }),
        shape === "pill" &&
          (backgroundColor ? badgeTextFallback(mono) : badgeTextVariants({ variant, mono })),
        variant === "link" && "[a&]:hover:underline [a&]:focus-visible:underline",
        // Tailwind's pulse is `BADGE_PULSE_MS` long and `BADGE_PULSE_LOW` faint, as on device.
        pulse && shape === "dot" && "motion-safe:animate-pulse",
        className,
      )}
      style={{
        ...(backgroundColor ? { backgroundColor } : {}),
        ...(textColor ? { color: textColor } : {}),
        ...style,
      }}
      // A dot carries meaning and no text, so it is named or it is decoration;
      // the same split `color-dot` makes, for the same reason.
      {...(shape === "dot" ? dotName : {})}
      {...props}
    >
      {/* `asChild` renders `children` and nothing beside it. `Slot` counts every child
          expression, a `null` included, so a second slot here — even one that is always
          empty under `asChild` — made it throw "failed to slot onto its children" (#152). */}
      {asChild ? children : pill}
    </Comp>
  );
}

export { badgeVariants };
